#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;class CostStrategy{public:virtual~CostStrategy()=default;virtual double cost(double w,double d,int p)const=0;};class StandardCost:public CostStrategy{public:double cost(double w,double d,int p)const override{return 20+w*4+d*.8+(p>1?50:0);}};class ExpressCost:public CostStrategy{public:double cost(double w,double d,int p)const override{return(30+w*6+d*1.2)*(p>1?1.25:1);}};struct Package{int id;double weight,distance;string destination;int priority;string status="Registered";int vehicleId=0;};class Vehicle{protected:int id;double capacity,used=0;public:Vehicle(int i,double c):id(i),capacity(c){}virtual~Vehicle()=default;int getId()const{return id;}virtual string type()const=0;bool assign(double w){if(used+w>capacity)return false;used+=w;return true;}void show()const{cout<<id<<" | "<<type()<<" | "<<used<<'/'<<capacity<<'\n';}};class Bike:public Vehicle{public:Bike(int i):Vehicle(i,50){}string type()const override{return"Bike";}};class Van:public Vehicle{public:Van(int i):Vehicle(i,1000){}string type()const override{return"Van";}};class Truck:public Vehicle{public:Truck(int i):Vehicle(i,5000){}string type()const override{return"Truck";}};class Logistics{vector<Package>packages;vector<shared_ptr<Vehicle>>vehicles;int next=1;Package*pkg(int id){for(auto&p:packages)if(p.id==id)return&p;return nullptr;}shared_ptr<Vehicle>veh(int id){for(auto&v:vehicles)if(v->getId()==id)return v;return{};}public:Logistics(){vehicles.push_back(make_shared<Bike>(1));vehicles.push_back(make_shared<Van>(2));vehicles.push_back(make_shared<Truck>(3));}void reg(){Package p;p.id=next++;cin>>p.weight;cin>>ws;getline(cin,p.destination);cin>>p.distance>>p.priority;if(p.weight>0&&p.distance>=0)packages.push_back(p);}void assign(){int p,v;cin>>p>>v;auto*x=pkg(p);auto y=veh(v);if(x&&y&&!x->vehicleId&&y->assign(x->weight)){x->vehicleId=v;x->status="Assigned";}}void status(){int id;string s;cin>>id>>s;if(auto*p=pkg(id))p->status=s;}void quote(){double w,d;int p,m;cin>>w>>d>>p>>m;unique_ptr<CostStrategy>s=m==2?unique_ptr<CostStrategy>(new ExpressCost):unique_ptr<CostStrategy>(new StandardCost);cout<<"Cost "<<s->cost(w,d,p)<<'\n';}void list()const{for(auto&p:packages)cout<<p.id<<" | "<<p.destination<<" | "<<p.weight<<"kg | "<<p.status<<" | vehicle "<<p.vehicleId<<'\n';for(auto&v:vehicles)v->show();}void deliver(){for(auto&p:packages)if(p.vehicleId&&p.status!="Delivered"){cout<<"Warehouse -> "<<p.destination<<" ("<<p.distance<<" km)\n";p.status="Delivered";}}void save()const{ofstream o("packages.txt");for(auto&p:packages)o<<p.id<<'|'<<p.weight<<'|'<<p.destination<<'|'<<p.priority<<'|'<<p.status<<'|'<<p.vehicleId<<'\n';}void run(){for(;;){cout<<"\nLogistics\n1 Register 2 Assign vehicle 3 Status 4 Quote 5 Deliver routes 6 List 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)reg();else if(c==2)assign();else if(c==3)status();else if(c==4)quote();else if(c==5)deliver();else if(c==6)list();}}};int main(){Logistics{}.run();}
